<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { api, session, loadSession, forgetSession } from './session'
interface Settings { name: string; slug: string; status: string; invitation_default_days: number; revision: number }
const form = reactive<Settings>({ name: '', slug: '', status: 'active', invitation_default_days: 7, revision: 0 }), confirmation = ref(''), busy = ref(false), error = ref(''), notice = ref('')
async function load() { try { Object.assign(form, await api<Settings>('/organization')) } catch (err) { error.value = (err as Error).message } }
async function save() { busy.value = true; error.value = ''; notice.value = ''; try { await api('/organization', { method: 'PATCH', body: JSON.stringify({ name: form.name, status: form.status, invitation_default_days: form.invitation_default_days, base_revision: form.revision, confirmation: confirmation.value }) }); if (form.status !== 'active') { forgetSession(); return } await load(); await loadSession(true); notice.value = 'Настройки организации сохранены' } catch (err) { error.value = (err as Error).message } finally { busy.value = false } }
onMounted(load)
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">ВАША ОРГАНИЗАЦИЯ</p><h1>Настройки организации</h1><p class="subtitle">{{ form.slug }}</p></div></div><p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="notice" class="form-success" role="status">{{ notice }}</p>
  <section class="editor-card account-card"><form @submit.prevent="save"><label class="form-field">Название организации<input v-model="form.name" maxlength="250" required :disabled="busy || session.user?.role !== 'org_admin'" /></label><label class="form-field">Срок приглашения по умолчанию, дней<input v-model.number="form.invitation_default_days" type="number" min="1" max="365" required :disabled="busy || session.user?.role !== 'org_admin'" /></label><p class="field-hint">Применяется к новым приглашениям кандидатов. Уже выданные ссылки не изменяются.</p><template v-if="session.user?.role === 'org_admin'"><label class="form-field">Статус организации<select v-model="form.status" :disabled="busy"><option value="active">Активна</option><option value="suspended">Приостановлена</option><option value="archived">В архиве</option></select></label><template v-if="form.status !== 'active'"><p class="form-error">Доступ всех сотрудников и кандидатов будет закрыт, сессии завершены. Данные сохранятся. Для возобновления потребуется оператор платформы.</p><label class="form-field">Подтверждение закрытия доступа<input v-model="confirmation" placeholder="ЗАКРЫТЬ ДОСТУП" required /></label></template><button class="primary-button" :disabled="busy || (form.status !== 'active' && confirmation !== 'ЗАКРЫТЬ ДОСТУП')">Сохранить настройки</button></template><p v-else class="muted-text">Настройки изменяет администратор организации.</p></form></section>
  <section class="editor-card account-card"><h2>Доступ и безопасность</h2><RouterLink to="/security" class="back-link">Пароль и двухфакторная защита</RouterLink><RouterLink v-if="session.user?.role === 'org_admin'" to="/team" class="back-link">Управление командой</RouterLink></section>
</template>
